-- Pinças: fotos refeitas em alta resolução com contorno limpo
INSERT INTO "stored_files" ("id","area","fileName","mimeType","sizeBytes","data","createdAt")
SELECT gen_random_uuid(),'products','edel-pi-inx-pf-v3.webp','image/webp',13442,decode('','hex'),now() WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName"='edel-pi-inx-pf-v3.webp');
DELETE FROM "product_images" i USING "products" p WHERE p."id"=i."productId" AND p."sku"='PIN-INX-PFI-006-2271504' AND i."fileName"<>'edel-pi-inx-pf-v3.webp';
